'use strict';
/* MICRO Q3327 FINAL VALIDATION — no optimization, fixed candidate only. */
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function ema(p){let a=new Float64Array(M.length),k=2/(p+1),x=M[0].c;for(let i=0;i<M.length;i++){x=i?M[i].c*k+x*(1-k):x;a[i]=x}return a}function atr(p=14){let a=new Float64Array(M.length);for(let i=p;i<M.length;i++){let s=0;for(let j=i-p+1;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));a[i]=s/p}return a}const E9=ema(9),E21=ema(21),E50=ema(50),A=atr();
const BASE={name:'Q1164 BASE',block:[16,17,20],sep:.15,imp:1.3,body:.65,pos:.78,rmin:.12,rmax:.45};const Q={name:'Q3327',block:[16,17,20,21],sep:.15,imp:1.4,body:.75,pos:.78,rmin:.12,rmax:.35};
function signals(q){let z=[];for(let i=60;i<M.length-1;i++){let b=M[i],a=A[i],hr=new Date(b.t).getUTCHours();if(q.block.includes(hr)||!(a>0)||!(E9[i]>E21[i]&&E21[i]>E50[i]&&E21[i]>E21[i-3]))continue;let rg=b.h-b.l;if(!(rg>0)||Math.abs(b.c-b.o)/rg<q.body||(b.c-b.l)/rg<q.pos||Math.abs(E9[i]-E21[i])/a<q.sep||b.c<=M[i-1].h)continue;let is=i-4,ie=i-2,raw=M[ie].c-M[is].o;if(!(raw>0)||raw/a<q.imp)continue;let pl=Infinity;for(let j=ie+1;j<i;j++)pl=Math.min(pl,M[j].l);let retr=(M[ie].c-pl)/raw;if(retr<q.rmin||retr>q.rmax)continue;z.push(i)}return z}
function trades(q){let sig=new Set(signals(q)),out=[],p=null;for(let i=60;i<M.length;i++){if(p){let b=M[i],sl=b.l<=p.sl,tp=b.h>=p.tp;if(sl||tp||i-p.ei+1>=10){let px=sl?p.sl:tp?p.tp:b.c;out.push({t:M[p.si].t,r:(px-p.en)/p.risk});p=null}if(p)continue}let si=i-1;if(sig.has(si)){let en=M[i].o,risk=2*A[si];p={en,risk,sl:en-risk,tp:en+risk,ei:i,si}}}return out}
function S(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else if(x.r<0){gl-=x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
const TB=trades(BASE),TQ=trades(Q),start=M[0].t,end=M[M.length-1].t;function range(T,a,b){return S(T.filter(x=>x.t>=a&&x.t<b))}function row(label,a,b){console.log(label.padEnd(16),'BASE',F(range(TB,a,b)),'| Q3327',F(range(TQ,a,b)))}
console.log('MICRO — Q3327 FINAL VALIDATION');console.log('FIXED candidate; ZERO parameter selection here');console.log(new Date(start).toISOString(),'→',new Date(end).toISOString());console.log('\n=== FULL ===');row('FULL',start,end+1);
console.log('\n=== CHRONO QUARTERS ===');for(let k=0;k<4;k++){let a=start+(end-start)*k/4,b=k===3?end+1:start+(end-start)*(k+1)/4;row(`Q${k+1}`,a,b)}
console.log('\n=== ROLLING RECENT ===');for(const d of [180,120,90,60,30])row(`LAST ${d}D`,end-d*864e5,end+1);
console.log('\n=== MONTH BLOCKS (recent 6) ===');for(let k=5;k>=0;k--){let d=new Date(end),y=d.getUTCFullYear(),m=d.getUTCMonth()-k,a=Date.UTC(y,m,1),b=Date.UTC(y,m+1,1);row(new Date(a).toISOString().slice(0,7),a,b)}
console.log('\n=== WALK-FORWARD 5 FOLDS ===');for(let k=0;k<5;k++){let a=start+(end-start)*k/5,b=k===4?end+1:start+(end-start)*(k+1)/5;row(`FOLD ${k+1}`,a,b)}
let q=S(TQ),b=S(TB),recent=range(TQ,end-90*864e5,end+1);let pass=q.wr>=62&&q.pf>=1.7&&q.dd<=b.dd&&q.ls<=b.ls&&recent.n>=20&&recent.pf>=1.2;console.log('\n=== GATE ===');console.log(`Q3327 ${F(q)}`);console.log(pass?'✅ PASS FINAL GATE — candidate is eligible for live implementation.':'❌ FAIL FINAL GATE — do NOT change live Micro.');
